content.text:
请对以下 case 进行三维加权评分。

=== case_id ===
Case-23-countdown-450

=== 用户原始指令 (query.txt) ===
帮我弄个倒计时卡片,数字放背景图上,点一下能进系统,能读日历,要看到已完成

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "帮我弄个倒计时卡片,数字放背景图上,点一下能进系统,能读日历,要看到已完成",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToIntent",
      "args": {
        "intentName": "ViewCalendarEvent",
        "params": {
          "entityId": {
            "path": "/data/calendar/items/0/entityId"
          }
        }
      }
    }
  ],
  "dataModel": {
    "value": {
      "countdown": {
        "title": "纪念日倒计时",
        "numberText": "已完成",
        "sourceText": "正在读取日历",
        "actionText": "查看日程"
      },
      "asset": {
        "scheduleIcon": "resources/base/media/icon_schedule.png"
      },
      "data": {
        "calendar": {
          "items": [
            {
              "entityName": "calendar",
              "entityId": "calendar_placeholder",
              "title": "纪念日",
              "dtStart": "00:00",
              "dtEnd": "23:59",
              "importantEventType": 2
            }
          ]
        }
      },
      "state": {
        "loading": true,
        "completed": true
      }
    }
  },
  "assetCandidates": [
    {
      "assetRef": "schedule_icon",
      "src": "resources/base/media/icon_schedule.png",
      "use": "calendar glyph",
      "description": "日程图标素材，适合表达日历读取、纪念日和倒计时入口。",
      "bindTo": "/asset/scheduleIcon",
      "static": true
    }
  ]
}

